      "content": "//#region session-colors: host half
/**
 * DeepSeek Harness plugin — per-session color tags, host half.
 *
 * Owns the durable `sessionId → color` store and serves it to the web client
 * through one prefixed HTTP route on the host webserver:
 *
 *   GET    /session-colors/api/colors              → { colors: { [sessionId]: "#rrggbb" } }
 *   PUT    /session-colors/api/colors/:sessionId   body { color: "#rrggbb" | null } → { colors }
 *   DELETE /session-colors/api/colors/:sessionId   → { colors }
 *
 * Storage is one JSON file under the harness home's `storages/` directory
 * (`$DSH_HOME` or `~/.dsh`), written atomically (temp file + rename).
 *
 * The same loader entry also advertises this package's `dsh.client` bundle,
 * so mounting this entry is what makes the browser half load.
 */
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

/** Cordis plugin name. */
const name = "session-colors";

/** No static service requirements; the webserver seat is injected in apply(). */
const inject = [];

/** Strict hex color accepted by the API (`#rgb` expanded to `#rrggbb`). */
const COLOR_PATTERN = /^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/;

/** Session ids look like `session-<uuid>`; keep the route param conservative. */
const SESSION_ID_PATTERN = /^[A-Za-z0-9](?:[A-Za-z0-9._:-]{0,199}[A-Za-z0-9])?$/;

/** Request body cap — one color per request, so this is generous. */
const MAX_BODY_BYTES = 16 * 1024;

/**
 * The registered route prefix. Prefix handlers receive the full request path
 * (the webserver does not strip the prefix), so route matching includes it.
 */
const ROUTE_PREFIX = "/session-colors";

/** `GET /session-colors/api/colors` */
const COLORS_PATH = `${ROUTE_PREFIX}/api/colors`;

/** `PUT|DELETE /session-colors/api/colors/:sessionId` */
const COLORS_ID_PATTERN = /^\/session-colors\/api\/colors\/([^/]+)$/;

/** On-disk shape. Bump `version` when the schema evolves. */
const STORE_VERSION = 1;

/**
 * Expand a validated hex color to the canonical 6-digit lowercase form.
 * @param {string} color - a string already matched against COLOR_PATTERN.
 * @returns {string} canonical `#rrggbb`.
 */
function canonicalColor(color) {
	const hex = color.slice(1);
	if (hex.length === 3) {
		const doubled = [...hex].map((c) => c + c).join("");
		return `#${doubled.toLowerCase()}`;
	}
	return `#${hex.toLowerCase()}`;
}

/**
 * Resolve the harness home the same way `dsh-home-paths` defaults do:
 * `$DSH_HOME` when non-blank, otherwise `~/.dsh`.
 * @returns {string} absolute harness home path.
 */
function harnessHome() {
	const fromEnv = process.env.DSH_HOME;
	if (typeof fromEnv === "string" && fromEnv.trim().length > 0) return fromEnv;
	return join(homedir(), ".dsh");
}

/**
 * Serialize one store read result into the API response body.
 * @param {Record<string, string>} colors - the color map.
 * @returns {string} JSON body.
 */
function colorsBody(colors) {
	return JSON.stringify({ colors }) + "\n";
}

/** Serialize one error response body. */
function errorBody(message) {
	return JSON.stringify({ error: message }) + "\n";
}

/**
 * A tiny in-process write queue so concurrent PUTs cannot interleave
 * read-modify-write cycles on the store file.
 */
class Store {
	#path;
	#colors = {};
	#loaded = false;
	#queue = Promise.resolve();

	/** @param {string} path - absolute store file path. */
	constructor(path) {
		this.#path = path;
	}

	/** Read the store once, tolerating absence and unrecoverable corruption. */
	async #load() {
		if (this.#loaded) return;
		let raw;
		try {
			raw = await readFile(this.#path, "utf8");
		} catch (error) {
			if (/** @type {NodeJS.ErrnoException} */ (error).code === "ENOENT") {
				this.#loaded = true;
				return;
			}
			throw error;
		}
		try {
			const parsed = JSON.parse(raw);
			if (parsed !== null && typeof parsed === "object" && parsed.colors !== null && typeof parsed.colors === "object") {
				const colors = {};
				for (const [id, color] of Object.entries(parsed.colors)) {
					if (typeof color === "string" && COLOR_PATTERN.test(color) && SESSION_ID_PATTERN.test(id)) colors[id] = canonicalColor(color);
				}
				this.#colors = colors;
			}
		} catch {
			// A torn or hand-mangled file must not take the plugin down; the next
			// write replaces it wholesale with a valid store.
		}
		this.#loaded = true;
	}

	/** Atomically persist the current map. */
	async #persist() {
		await mkdir(join(this.#path, ".."), { recursive: true });
		const temp = `${this.#path}.${process.pid}.${Date.now()}.tmp`;
		const body = `${JSON.stringify({ version: STORE_VERSION, colors: this.#colors }, null, 2)}\n`;
		await writeFile(temp, body, "utf8");
		await rename(temp, this.#path);
	}

	/**
	 * Run one read-modify-write cycle behind the write queue.
	 * @template T
	 * @param {() => Promise<T>} task - closure over a snapshot clone.
	 * @returns {Promise<T>} the task's result.
	 */
	#enqueue(task) {
		const run = this.#queue.then(task);
		// Keep the queue alive regardless of individual failures.
		this.#queue = run.then(() => undefined, () => undefined);
		return run;
	}

	/**
	 * Snapshot the current color map (a clone — callers may hold it).
	 * @returns {Promise<Record<string, string>>}
	 */
	snapshot() {
		return this.#enqueue(async () => {
			await this.#load();
			return { ...this.#colors };
		});
	}

	/**
	 * Set or clear one session's color and persist.
	 * @param {string} sessionId - validated session id.
	 * @param {string | null} color - canonical color, or null to clear.
	 * @returns {Promise<Record<string, string>>} the map after the change.
	 */
	set(sessionId, color) {
		return this.#enqueue(async () => {
			await this.#load();
			if (color === null) delete this.#colors[sessionId];
			else this.#colors[sessionId] = color;
			await this.#persist();
			return { ...this.#colors };
		});
	}
}

/**
 * Host plugin body: own the store and expose the HTTP route.
 * @param {import("@deepseek-ai/cordis").Context} ctx - plugin context.
 */
async function apply(ctx) {
	const store = new Store(join(harnessHome(), "storages", "session-colors.json"));

	/** Answer one HTTP request for the /session-colors prefix. */
	const handler = async (req, res) => {
		const respond = (status, body, contentType = "application/json; charset=utf-8") => {
			res.writeHead(status, { "content-type": contentType, "cache-control": "no-store" });
			res.end(body);
		};
		try {
			const url = new URL(/** @type {string} */ (req.url), "http://dsh.invalid");
			if (url.pathname === COLORS_PATH) {
				if (req.method !== "GET" && req.method !== "HEAD") return respond(405, errorBody("method not allowed"));
				return respond(200, colorsBody(await store.snapshot()));
			}
			const match = COLORS_ID_PATTERN.exec(url.pathname);
			if (match) {
				if (req.method !== "PUT" && req.method !== "DELETE") return respond(405, errorBody("method not allowed"));
				const sessionId = decodeURIComponent(match[1]);
				if (!SESSION_ID_PATTERN.test(sessionId)) return respond(400, errorBody("invalid session id"));
				if (req.method === "DELETE") return respond(200, colorsBody(await store.set(sessionId, null)));
				const raw = await readBody(req);
				if (raw === undefined) return respond(400, errorBody("unreadable request body"));
				let parsed;
				try {
					parsed = JSON.parse(raw);
				} catch {
					return respond(400, errorBody("request body must be JSON"));
				}
				const color = parsed === null || typeof parsed !== "object" ? undefined : /** @type {{color?: unknown}} */ (parsed).color;
				if (color === null) return respond(200, colorsBody(await store.set(sessionId, null)));
				if (typeof color !== "string" || !COLOR_PATTERN.test(color)) return respond(400, errorBody("color must be a #rgb/#rrggbb hex string or null"));
				return respond(200, colorsBody(await store.set(sessionId, canonicalColor(color))));
			}
			return respond(404, errorBody("not found"));
		} catch (error) {
			ctx.logger?.error?.(error);
			if (!res.headersSent) respond(500, errorBody("session-colors internal error"));
			else res.end();
		}
	};

	const registerWebCarrier = (webCtx) => {
		webCtx.effect(() => /** @type {import("@deepseek-ai/dsh-host-webserver").WebServer} */ (webCtx.webServer).register({
			kind: "prefix",
			path: "/session-colors",
			handler: /** @type {(req: import("node:http").IncomingMessage, res: import("node:http").ServerResponse) => void} */ (handler)
		}), "session-colors: api route");
	};

	if (ctx.get("webServer") === undefined) ctx.inject(["webServer"], registerWebCarrier);
	else registerWebCarrier(ctx);
}

/**
 * Read and hard-cap a request body.
 * @param {import("node:http").IncomingMessage} req
 * @returns {Promise<string | undefined>} the body, or undefined when over cap.
 */
function readBody(req) {
	return new Promise((resolve) => {
		let size = 0;
		/** @type {Buffer[]} */
		const chunks = [];
		req.on("data", (chunk) => {
			size += chunk.length;
			if (size > MAX_BODY_BYTES) {
				resolve(undefined);
				req.destroy();
				return;
			}
			chunks.push(chunk);
		});
		req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
		req.on("error", () => resolve(undefined));
	});
}

export { apply, inject, name };
